    if not numbers:
        return []

    # Initialize rolling_max list with the first element
    rolling_max_list = [numbers[0]]

    for num in numbers[1:]:
        # If the current number is greater than the last element in the rolling_max_list
        if num > rolling_max_list[-1]:
            rolling_max_list.append(num)
        else:
            # If not, append the last element in the rolling_max_list instead
            rolling_max_list.append(rolling_max_list[-1])

    return rolling_max_list
