def encode(message: str) -> str:
    vowels = 'AEIOU'
    encoded_message = []

    for char in message:
        if char.isalpha():
            # Swap case
            if char.islower():
                encoded_message.append(char.upper())
            else:
                encoded_message.append(char.lower())

            # Replace with the next vowel
            idx = vowels.index(char)
            if idx < len(vowels) - 1:
                encoded_message.append(vowels[idx + 1])
            else:
                encoded_message.append(vowels[0])
        else:
            encoded_message.append(char)

    return ''.join(encoded_message)
