from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    dp = [[[float('inf')] * (k + 1) for _ in range(n)] for _ in range(n)]
    min_list = [[[[] for _ in range(k + 1)] for _ in range(n)] for _ in range(n)]

    for j in range(n):
        for i in range(n):
            dp[j][i][1] = (grid[i][j], (i, j))

    for h in range(2, k + 1):
        for j in range(n):
            for i in range(n):
                for d in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    dj, di = d
                    if i + dj >= 0 and i + dj < n and j + di >= 0 and j + di < n:
                        next_val = grid[i + dj][j + di]
                        next_idx = (-1, -1)
                        for ij in dp[j + dj][i + di]:
                            if ij[0] == next_val:
                                next_idx = ij[1:]
                                break
                        if next_idx != (-1, -1):
                            next_pos = next_idx[-1] + 1
                            min_list[j + dj][i + di][next_pos].append(next_val)
                            dp[j + dj][i + di][next_pos] = dp[j + dj][i + di][next_pos] + 1
                        else:
                            dp[j + dj][i + di][h] = 0

    ans = []
    for i in range(n):
        for j in range(n):
            if k == 1:
                ans.append(grid[i][j])
                return ans
            lst = min_list[i][j]
            if k >= len(lst):
                continue
            cand = lst[:k]
            if dp[j][i][k][len(lst)] != float('inf'):
                cand = cand + [grid[j][i]]
                for idx in range(len(dp[j][i][k])):
                    if dp[j][i][k][idx] == dp[i][j][k][len(lst)][idx]:
                        cand[idx] = cand[idx] + grid[i][j]

    return cand[::-1]
