import re

def is_nested(string):
    stack = []
    nested = False

    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']' and len(stack) > 0:
            nested = True
            if stack[-1] == '[' and is_valid_bracket_sequence(stack[1:]):
                stack.pop()
                stack.append(char)
        elif char == ']' and stack[-1] == ']':
            return False

    return nested and not stack

def is_valid_bracket_sequence(sequence):
    stack = []
    balanced = True
    index = 0

    while index < len(sequence) and balanced:
        if sequence[index] == '[':
            stack.append(index)
        elif sequence[index] == ']':
            if not stack:
                balanced = False
            else:
                stack.pop()

        index += 1

    return balanced and len(stack) == 0

